package dev.votex.config;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import static org.junit.jupiter.api.Assertions.*;
class ConfigTest {
 @TempDir Path dir;
 @Test void moduleChangesSurviveReload()throws Exception{Path p=dir.resolve("modules.json");var r=new ModuleRegistry(p);assertTrue(r.enabled("fps"));r.toggle("fps");var second=new ModuleRegistry(p);second.load();assertFalse(second.enabled("fps"));assertFalse(second.enabled("coordinates"));}
 @Test void badConfigIsPreserved()throws Exception{Path p=dir.resolve("modules.json");Files.writeString(p,"{\"schemaVersion\":99}");var r=new ModuleRegistry(p);assertThrows(java.io.IOException.class,r::load);assertEquals("{\"schemaVersion\":99}",Files.readString(p));}
 @Test void rejectsCodeAndInvalidThemeValues()throws Exception{Path p=dir.resolve("theme.json");Files.writeString(p,"{\"schemaVersion\":1,\"accent\":\"javascript:alert(1)\"}");assertThrows(Exception.class,()->ThemeConfig.read(p));Files.writeString(p,"{\"schemaVersion\":1,\"blur\":0,\"wobble\":101}");assertThrows(Exception.class,()->ThemeConfig.read(p));}
 @Test void importsCompatibleThemeValues()throws Exception{Path p=dir.resolve("theme.json");Files.writeString(p,"{\"schemaVersion\":1,\"accent\":\"#45d8ff\",\"wobble\":0,\"transparency\":50}");var t=ThemeConfig.read(p);assertEquals(0xff45d8ff,t.accent());assertEquals(0,t.wobble());assertTrue((t.panel()>>>24)>0);}
 @Test void oldHudConfigMigratesWithoutChangingEnabledModules()throws Exception{Path p=dir.resolve("modules.json");Files.writeString(p,"{\"schemaVersion\":1,\"enabled\":{\"fps\":false,\"coordinates\":true,\"clock\":false},\"x\":25,\"y\":33,\"scale\":100}");var r=new ModuleRegistry(p);r.load();assertTrue(r.enabled("coordinates"));assertFalse(r.enabled("fps"));assertFalse(r.enabled("keystrokes"));assertEquals(25,r.config().x);assertNotNull(r.config().positions);}
 @Test void hudPositionsSurviveReload()throws Exception{Path p=dir.resolve("modules.json");var r=new ModuleRegistry(p);r.config().positions.put("fps",new ModuleRegistry.Position(220,120));r.save();var loaded=new ModuleRegistry(p);loaded.load();assertEquals(220,loaded.config().positions.get("fps").x);}
 @Test void unknownModulesAreRejected(){assertThrows(IllegalArgumentException.class,()->new ModuleRegistry(dir.resolve("x.json")).toggle("unknown"));}
 // Light Level is a world overlay ("Grafik") since LightLevelOverlay; it is no longer a positioned HUD widget.
 @Test void catalogueHasMoreThanTwentyRealHudElementsAndSeparateFeatureModules(){assertEquals(27,ModuleRegistry.HUD_MODULES.size());assertTrue(ModuleRegistry.MODULES.stream().anyMatch(m->m.id().equals("light")&&m.category().equals("Grafik")));assertTrue(ModuleRegistry.HUD_MODULES.stream().noneMatch(m->m.id().equals("light")));assertTrue(ModuleRegistry.HUD_MODULES.stream().allMatch(m->m.category().equals("HUD")));assertEquals(ModuleRegistry.MODULES.size(),ModuleRegistry.MODULES.stream().map(ModuleRegistry.Module::id).distinct().count());assertTrue(ModuleRegistry.MODULES.stream().anyMatch(m->m.id().equals("item_physics")));}
 @Test void independentHudAppearanceAndMenuFlagsSurviveReload()throws Exception{var r=new ModuleRegistry(dir.resolve("appearance.json"));var a=new ModuleRegistry.Appearance();a.scale=160;a.background=25;a.accent=false;r.config().appearance.put("coordinates",a);r.config().menuAnimations=false;r.config().chatStackDuplicates=false;r.save();var loaded=new ModuleRegistry(dir.resolve("appearance.json"));loaded.load();assertEquals(160,loaded.config().appearance.get("coordinates").scale);assertEquals(25,loaded.config().appearance.get("coordinates").background);assertFalse(loaded.config().appearance.get("coordinates").accent);assertFalse(loaded.config().appearance.containsKey("fps"));assertFalse(loaded.config().menuAnimations);assertFalse(loaded.config().chatStackDuplicates);}
 @Test void invalidHudAppearanceDoesNotOverwriteOriginal()throws Exception{Path p=dir.resolve("invalid-appearance.json");String original="{\"schemaVersion\":1,\"enabled\":{},\"appearance\":{\"fps\":{\"scale\":5000,\"background\":70}}}";Files.writeString(p,original);assertThrows(java.io.IOException.class,()->new ModuleRegistry(p).load());assertEquals(original,Files.readString(p));}
}
